import React, { useState } from "react";

const AdopterDashboard = () => {
    const [filters, setFilters] = useState({
        type: "",
        breed: "",
        age: ""
    });

    return (
        <div style={{ padding: "30px" }}>

            {/* HEADER */}
            <h1 style={{ marginBottom: "10px" }}>🐾 Adopter Dashboard</h1>
            <p style={{ color: "#555", marginBottom: "20px" }}>
                Bine ai revenit! Explorează animalele disponibile pentru adopție.
            </p>

            {/* FILTERS */}
            <div
                style={{
                    display: "flex",
                    gap: "20px",
                    marginBottom: "30px",
                    padding: "20px",
                    background: "#f7f7f7",
                    borderRadius: "8px",
                }}
            >
                <div>
                    <label>Tip animal</label><br />
                    <select
                        value={filters.type}
                        onChange={(e) => setFilters({ ...filters, type: e.target.value })}
                    >
                        <option value="">Toate</option>
                        <option value="dog">Câine</option>
                        <option value="cat">Pisică</option>
                    </select>
                </div>

                <div>
                    <label>Rasă</label><br />
                    <input
                        type="text"
                        placeholder="ex: Husky"
                        value={filters.breed}
                        onChange={(e) => setFilters({ ...filters, breed: e.target.value })}
                    />
                </div>

                <div>
                    <label>Vârsta</label><br />
                    <select
                        value={filters.age}
                        onChange={(e) => setFilters({ ...filters, age: e.target.value })}
                    >
                        <option value="">Oricare</option>
                        <option value="puppy">Pui</option>
                        <option value="adult">Adult</option>
                        <option value="senior">Senior</option>
                    </select>
                </div>
            </div>

            {/* LISTA DE ANIMALE – momentan doar placeholder */}
            <h2 style={{ marginBottom: "15px" }}>Animale disponibile</h2>

            <p style={{ color: "#777" }}>
                Aici vei afișa cardurile animalelor încărcate de adăposturi.
                Conectarea la baza de date urmează după ce studentul 2 finalizează partea lui.
            </p>

            <div style={{ display: "flex", gap: "20px", flexWrap: "wrap" }}>
                {/* Exemplu card */}
                <div style={{
                    width: "250px",
                    border: "1px solid #ddd",
                    borderRadius: "10px",
                    padding: "10px",
                    background: "white"
                }}>
                    <img
                        src="https://place-puppy.com/300x300"
                        alt="dog"
                        style={{ width: "100%", borderRadius: "10px", marginBottom: "10px" }}
                    />
                    <h3>Rex</h3>
                    <p>Husky · 2 ani</p>
                    <button style={{
                        marginTop: "10px",
                        padding: "8px 12px",
                        background: "#4285f4",
                        color: "white",
                        border: "none",
                        borderRadius: "6px"
                    }}>
                        Vezi detalii
                    </button>
                </div>
            </div>

        </div>
    );
};

export default AdopterDashboard;
